/**
 * D. M. Raup's geometric model of shell coiling (1962, 1966).
 *
 * The shell is generated by sweeping a generating curve (an ellipse, the
 * "aperture") along a logarithmic spiral around a fixed axis. After each full
 * revolution (Δθ = 2π) the generating curve is scaled by W.
 *
 * Right-handed mathematical frame (x, y, z) with z = coiling axis:
 *
 *   g(θ)  = W^(θ / 2π)                       growth factor
 *   r_c   = (1 + D) / 2                       distance from the aperture centre to the axis
 *   a     = (1 − D) / 2                       radial semi-axis of the ellipse
 *   b     = S · a                             axial semi-axis of the ellipse
 *
 *   x(θ,φ) = g · (r_c + a cos φ) · cos θ
 *   y(θ,φ) = g · (r_c + a cos φ) · sin θ · ε  (ε = −1 dextral, +1 sinistral)
 *   z(θ,φ) = g · (−T · r_c + b sin φ)
 *
 * At the final aperture (θ = 0, g = 1) the inner edge lies at distance D from
 * the axis and the outer edge at distance 1, so D = r_inner / r_outer, as Raup
 * defines it. θ runs over [−2π·N, 0]; the apex (θ → −∞) is at the origin.
 *
 * Mapping to Three.js (Y up): X = x, Y = z, Z = −y. With hand = −ε:
 *   Z = hand · g · (r_c + a cos φ) · sin θ
 *
 * Mirror valve (bivalves): reflection across the plane of the aperture,
 * y → −y (Z → −Z in Three.js).
 *
 * Ornament (optional): a relief added to the generating curve along its
 * outward normal n(φ), in units of the aperture radius, so it grows with the
 * shell like the rest of the aperture:
 *
 *   P'(θ,φ) = P(θ,φ) + g · a · δ(θ,φ) · n(φ)
 *   δ = h_r · R(θ) + h_c · C(u)            reticulate (ribs and cords add up)
 *   δ = (h_r + h_c) · R(θ) · C(u)          nodules (only where they cross)
 *
 * R and C are periodic bumps: n_r axial ribs per whorl along θ and n_c spiral
 * cords around the margin (u = arc length). Each bump has the shape cos² and
 * covers a fraction w of the spacing (w = 1: a smooth wave; small w: thin ribs).
 * This is a descriptive model of ornament (as in Cortie, 1993, and Fowler,
 * Meinhardt & Prusinkiewicz, 1992), not a mechanism.
 */

/**
 * Periodic bump of height 1: cos² over a fraction `w` of each period, zero
 * elsewhere. `t` is measured in periods; bumps are centred on whole numbers.
 */
export function bump(t, w) {
  const d = Math.abs(t - Math.round(t)); // distance to the nearest centre, 0–0.5
  const half = Math.max(w, 1e-3) / 2;
  if (d >= half) return 0;
  const c = Math.cos((Math.PI / 2) * (d / half));
  return c * c;
}

/** True when the parameters ask for some relief. */
export const hasOrnament = (p) => (p.ribN > 0 && p.ribH > 0) || (p.cordN > 0 && p.cordH > 0);

/**
 * @param {object} p
 * @param {number} p.W  whorl expansion rate (> 1)
 * @param {number} p.D  relative distance of the generating curve from the axis [0, 1)
 * @param {number} p.T  translation rate along the axis
 * @param {number} p.S  shape of the generating curve (b / a)
 * @param {number} p.turns        number of whorls
 * @param {number} p.hand         +1 dextral, −1 sinistral
 * @param {boolean} p.mirror      add the mirror valve
 * @param {number} p.grow         fraction of growth shown (0, 1]
 * @param {number} p.segPerTurn   segments in θ per whorl
 * @param {number} p.segPhi       segments in φ around the aperture
 * @param {number} p.spiralLines  number of spiral lines (along θ)
 * @param {number} p.ringsPerTurn number of growth lines per whorl
 * @param {number} [p.ribN]       axial ribs per whorl (0: none)
 * @param {number} [p.ribH]       rib height, relative to the aperture radius
 * @param {number} [p.ribW]       rib width, fraction of the spacing (0, 1]
 * @param {number} [p.cordN]      spiral cords around the aperture (0: none)
 * @param {number} [p.cordH]      cord height, relative to the aperture radius
 * @param {number} [p.cordW]      cord width, fraction of the spacing (0, 1]
 * @param {boolean} [p.nodules]   relief only where ribs and cords cross
 * @param {number} p.size         largest dimension after normalisation
 * @returns {{positions: Float32Array, colors: Float32Array, uvs: Float32Array,
 *   indices: Uint32Array, lineIndices: Uint32Array, axis: object,
 *   derived: {rc: number, a: number, b: number}, grid: object, stats: object}}
 */
export function buildShell(p) {
  const W = Math.max(p.W, 1.0001);
  const { D, T, S, hand } = p;
  const segPhi = p.segPhi;
  const nTheta = Math.max(2, Math.round(p.turns * p.segPerTurn));
  const thetaMin = -2 * Math.PI * p.turns;
  const grow = p.grow ?? 1;
  const cutRow = Math.max(1, Math.round(grow * nTheta));
  const copies = p.mirror ? 2 : 1;

  const rc = (1 + D) / 2;
  const a = (1 - D) / 2;
  const b = S * a;

  // Column j = segPhi repeats j = 0 (the seam) so that the pattern texture
  // (u along the margin, v along θ) does not wrap around in the last triangle.
  const rows = nTheta + 1;
  const cols = segPhi + 1;
  const count = rows * cols;
  const positions = new Float32Array(count * 3 * copies);
  const colors = new Float32Array(count * 3 * copies);
  const uvs = new Float32Array(count * 2 * copies);

  const cosPhi = new Float32Array(cols);
  const sinPhi = new Float32Array(cols);
  for (let j = 0; j < segPhi; j++) {
    const phi = (j / segPhi) * Math.PI * 2;
    cosPhi[j] = Math.cos(phi);
    sinPhi[j] = Math.sin(phi);
  }
  cosPhi[segPhi] = cosPhi[0];
  sinPhi[segPhi] = sinPhi[0];

  // Pattern coordinate u: arc length along the margin (not the angle φ). In an
  // elliptical aperture (S ≠ 1) the same Δφ covers more or less margin; this way
  // the cells of Meinhardt's model are evenly spaced along the real margin.
  const arcU = new Float64Array(cols);
  {
    const sub = 8;
    let L = 0;
    for (let j = 0; j < segPhi; j++) {
      for (let q = 0; q < sub; q++) {
        const phi = ((j + (q + 0.5) / sub) / segPhi) * Math.PI * 2;
        L += Math.hypot(a * Math.sin(phi), S * a * Math.cos(phi));
      }
      arcU[j + 1] = L;
    }
    for (let j = 0; j <= segPhi; j++) arcU[j] = L > 0 ? arcU[j] / L : j / segPhi;
  }

  // Ornament: outward normal of the ellipse in the meridian plane, and the
  // cord profile around the margin (it depends only on the column)
  const ornament = hasOrnament(p);
  const ribN = p.ribN || 0, ribH = ribN > 0 ? p.ribH || 0 : 0, ribW = p.ribW ?? 0.5;
  const cordN = p.cordN || 0, cordH = cordN > 0 ? p.cordH || 0 : 0, cordW = p.cordW ?? 0.5;
  const nodules = !!p.nodules && ribH + cordH > 0;
  const nR = new Float64Array(cols), nZ = new Float64Array(cols), cord = new Float64Array(cols);
  if (ornament) {
    for (let j = 0; j < cols; j++) {
      const len = Math.hypot(b * cosPhi[j], a * sinPhi[j]) || 1;
      nR[j] = (b * cosPhi[j]) / len;
      nZ[j] = (a * sinPhi[j]) / len;
      cord[j] = cordN > 0 ? bump(arcU[j] * cordN, cordW) : nodules ? 1 : 0;
    }
  }

  const logW = Math.log(W);
  let minX = Infinity, minY = Infinity, minZ = Infinity;
  let maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity;

  for (let i = 0; i < rows; i++) {
    const theta = thetaMin + (i / nTheta) * (-thetaMin);
    const g = Math.exp((theta / (2 * Math.PI)) * logW);
    const ct = Math.cos(theta);
    const st = Math.sin(theta) * hand;
    // Growth bands (they only affect the colour in solid mode)
    const growth = 0.5 + 0.5 * Math.cos(theta * 3.0);
    // Axial ribs are counted from the final aperture, so the lip carries one
    const rib = ribN > 0 ? bump((theta / (2 * Math.PI)) * ribN, ribW) : nodules ? 1 : 0;
    for (let j = 0; j < cols; j++) {
      let delta = 0;
      if (ornament) delta = a * (nodules ? (ribH + cordH) * rib * cord[j] : ribH * rib + cordH * cord[j]);
      const R = g * (rc + a * cosPhi[j] + delta * nR[j]);
      const x = R * ct;
      const z = R * st;
      const y = g * (-T * rc + b * sinPhi[j] + delta * nZ[j]);
      const k = (i * cols + j) * 3;
      positions[k] = x;
      positions[k + 1] = y;
      positions[k + 2] = z;
      if (x < minX) minX = x; if (x > maxX) maxX = x;
      if (y < minY) minY = y; if (y > maxY) maxY = y;
      if (z < minZ) minZ = z; if (z > maxZ) maxZ = z;

      const spiral = 0.5 + 0.5 * Math.cos(j / segPhi * Math.PI * 2 * 6);
      const shade = 1 - 0.22 * Math.pow(growth, 6) - 0.08 * spiral * growth;
      colors[k] = shade;
      colors[k + 1] = shade * 0.97;
      colors[k + 2] = shade * 0.93;
      const u = (i * cols + j) * 2;
      uvs[u] = arcU[j];
      uvs[u + 1] = i / nTheta;
    }
  }

  if (p.mirror) {
    const n = count * 3;
    for (let k = 0; k < n; k += 3) {
      positions[n + k] = positions[k];
      positions[n + k + 1] = positions[k + 1];
      positions[n + k + 2] = -positions[k + 2];
    }
    colors.copyWithin(n, 0, n);
    uvs.copyWithin(count * 2, 0, count * 2);
    const lo = minZ;
    minZ = Math.min(minZ, -maxZ);
    maxZ = Math.max(maxZ, -lo);
  }

  // Normalise: centre at the origin and scale to a fixed size, so the camera
  // does not need to reframe when the parameters change. The complete shell is
  // always used, so the growth animation does not change scale.
  const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2, cz = (minZ + maxZ) / 2;
  const extent = Math.max(maxX - minX, maxY - minY, maxZ - minZ) || 1;
  const scale = p.size / extent;
  for (let k = 0; k < positions.length; k += 3) {
    positions[k] = (positions[k] - cx) * scale;
    positions[k + 1] = (positions[k + 1] - cy) * scale;
    positions[k + 2] = (positions[k + 2] - cz) * scale;
  }

  // Surface triangles (the aperture is a closed curve in φ)
  const triPerCopy = cutRow * segPhi * 6;
  const indices = new Uint32Array(triPerCopy * copies);
  let t = 0;
  for (let c = 0; c < copies; c++) {
    const off = c * count;
    // Front faces must point out of the tube (the pigmented exterior). Both the
    // dextral sense and the reflection of the mirror valve reverse the winding.
    const flip = (c === 1) !== (hand > 0);
    for (let i = 0; i < cutRow; i++) {
      for (let j = 0; j < segPhi; j++) {
        const v00 = off + i * cols + j, v01 = v00 + 1;
        const v10 = off + (i + 1) * cols + j, v11 = v10 + 1;
        if (flip) {
          indices[t++] = v00; indices[t++] = v01; indices[t++] = v10;
          indices[t++] = v01; indices[t++] = v11; indices[t++] = v10;
        } else {
          indices[t++] = v00; indices[t++] = v10; indices[t++] = v01;
          indices[t++] = v01; indices[t++] = v10; indices[t++] = v11;
        }
      }
    }
  }

  // Lines: spiral lines (constant φ) and growth lines (constant θ)
  const lineIdx = [];
  const nSpiral = Math.min(p.spiralLines, segPhi);
  const usedPhi = new Set();
  for (let m = 0; m < nSpiral; m++) usedPhi.add(Math.round((m * segPhi) / nSpiral) % segPhi);
  const usedTheta = new Set([cutRow]);
  const totalRings = p.ringsPerTurn > 0 ? Math.floor(p.turns * p.ringsPerTurn) : 0;
  for (let m = 1; m <= totalRings; m++) {
    // count from the aperture towards the apex so the aperture always has a ring
    const i = nTheta - Math.round((m * p.segPerTurn) / p.ringsPerTurn);
    if (i >= 0 && i <= cutRow) usedTheta.add(i);
  }
  for (let c = 0; c < copies; c++) {
    const off = c * count;
    for (const j of usedPhi) {
      for (let i = 0; i < cutRow; i++) lineIdx.push(off + i * cols + j, off + (i + 1) * cols + j);
    }
    for (const i of usedTheta) {
      for (let j = 0; j < segPhi; j++) lineIdx.push(off + i * cols + j, off + i * cols + j + 1);
    }
  }

  return {
    positions,
    colors,
    uvs,
    indices,
    lineIndices: new Uint32Array(lineIdx),
    // Coiling axis in normalised coordinates
    axis: { x: -cx * scale, z: -cz * scale, yTop: (maxY - cy) * scale, yBottom: (minY - cy) * scale },
    derived: { rc, a, b },
    // To average the seam normals (columns 0 and segPhi)
    grid: { rows, cols, copies, count },
    stats: { vertices: count * copies, triangles: indices.length / 3 },
  };
}
